#include <cstdio>
#include <vector>
using namespace std;
const int MAXV=1000000;
bool isPrimeSmall(int x){ if(x<2) return false; for(int i=2;i*i<=x;i++) if(x%i==0) return false; return true; }
int main(){
    vector<bool> comp(MAXV,false);
    comp[0]=comp[1]=true;
    for(long long i=2;i*i<MAXV;i++) if(!comp[i]) for(long long j=i*i;j<MAXV;j+=i) comp[j]=true;
    vector<int> prefix(MAXV+1,0);
    for(int i=0;i<MAXV;i++){
        bool dp=false;
        if(!comp[i]){
            int s=0,t=i; while(t){s+=t%10;t/=10;}
            if(isPrimeSmall(s)) dp=true;
        }
        prefix[i+1]=prefix[i]+(dp?1:0);
    }
    int n; scanf("%d",&n);
    for(int i=0;i<n;i++){
        int t1,t2; scanf("%d %d",&t1,&t2);
        printf("%d\n", prefix[t2+1]-prefix[t1]);
    }
}

